#include "stdafx.h"#include "TrendsRemoteClient.h"#include <time.h>KTrendsRemoteClient::KTrendsRemoteClient( LPSTR _ObjName ) :	IBaseModel ( _ObjName ){  TypeObj = RSU_Obj;}int KTrendsRemoteClient::Init( int ){  return 0;}int KTrendsRemoteClient::Step0(){  return __super::StepK0();}int KTrendsRemoteClient::Step1(){  LoadPlugins();  return 0;}int KTrendsRemoteClient::StepT(double dt){  time_t startTime = pSys ? pSys->startTime : time(NULL);  return __super::StepKT( dt, startTime );}void KTrendsRemoteClient::FillHeader(){  __super::FillHeader();  if( pSys )    pSys->nTrends = m_dwBklTotal;}// Запись в файл трендовvoid KTrendsRemoteClient::WriteTrends(){  __super::WriteTrends();  if( pSys )    pSys->nTrends = m_dwBklTotal;}